using System;
using UnityEngine;
using UnityEngine.Tilemaps;

/// <summary>
/// Baked content of one map for MapStreamer: tile layers as palette indices and every placed object.
/// Generated by Tools > Map > Import (TiledMapTools); do not edit by hand.
///
/// Map-local coordinates: x to the right, y up, (0, 0) = bottom-left corner of the map, 1 unit per cell
/// (times CellSize). Cell (x, y) is stored at index x + y * Width.
/// </summary>
public sealed class StreamedMapData : ScriptableObject
{
    [Serializable]
    public sealed class TileLayer
    {
        public string Name;
        public int SortingOrder;
        public TileBase[] Palette;
        /// <summary>0 = empty, otherwise Palette[value - 1].</summary>
        public ushort[] Cells;
    }

    [Serializable]
    public struct PlacedObject
    {
        public ushort Prefab;
        /// <summary>Map-local position of the object's pivot (its feet).</summary>
        public Vector2 Position;
        public bool FlipX;
    }

    public int Width;
    public int Height;
    public Vector2 CellSize = Vector2.one;
    public bool WrapX = true;
    public bool WrapY = true;

    public TileLayer[] TileLayers = Array.Empty<TileLayer>();
    public GameObject[] Prefabs = Array.Empty<GameObject>();
    public PlacedObject[] Objects = Array.Empty<PlacedObject>();

    [Header("Object visual extents around the pivot (world units, max over all prefabs)")]
    public float MaxExtentLeft;
    public float MaxExtentRight;
    public float MaxExtentUp;
    public float MaxExtentDown;

    public Vector2 WorldSize => new Vector2(Width * CellSize.x, Height * CellSize.y);
}
